function is_undulating(n) {
  if (n < 10) return false; // Single digit numbers are not undulating

  const str = n.toString();
  const len = str.length;

  for (let i = 1; i < len - 1; i++) {
    if (str[i] !== str[i - 1] && str[i] !== str[i + 1]) {
      return false;
    }
  }

