function max_sum(arr){
    const n = arr.length;
    const dp = new Array(n).fill(0);
    const dpDesc = new Array(n).fill(0);

    // Calculate the maximum sum of increasing bitonic subsequence
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[j] < arr[i] && dp[j] + arr[i] > dp[i]) {
                dp[i] = dp[j] + arr[i];
            }
        }
    }

    // Calculate the maximum sum of decreasing bitonic subsequence
    for (let i = n - 1; i >= 0; i--) {
        for (let j = i + 1; j < n; j++) {
            if (arr[j] < arr[i] && dpDesc[j] + arr[i] > dpDesc[i]) {
                dpDesc[i] = dpDesc[j] + arr[i];
            }
        }
    }

    // Find the maximum sum of the bitonic subsequence
    let maxSum = 0;
    for (let i = 0; i < n; i++) {
        maxSum = Math.max(maxSum, dp[i] + dpDesc[i] - arr[i]);
    }

    return maxSum;
}

function max_sum(arr){
