    const dp_desc = new Array(n).fill(0);

    // Fill dp array for increasing subsequence
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] > arr[j]) {
                dp[i] = Math.max(dp[i], dp[j] + arr[i]);
            }
        }
    }

    // Fill dp_desc array for decreasing subsequence
    for (let i = n - 1; i >= 0; i--) {
        for (let j = n - 1; j > i; j--) {
            if (arr[i] > arr[j]) {
                dp_desc[i] = Math.max(dp_desc[i], dp_desc[j] + arr[i]);
            }
        }
    }

    // Find the maximum sum of bitonic subsequence
    let max_sum = 0;
    for (let i = 0; i < n; i++) {
        max_sum = Math.max(max_sum, dp[i] + dp_desc[i] - arr[i]);
    }

