  let array = Array.from(iterable);

  // Build the heap
  for (let i = Math.floor(array.length / 2 - 1); i >= 0; i--) {
    heapify(array, array.length, i);
  }

  // Sort the array
  for (let i = array.length - 1; i > 0; i--) {
    // Swap the root with the last element
    [array[0], array[i]] = [array[i], array[0]];
    // Heapify the root
    heapify(array, i, 0);
  }

