        }
    }

    while (i < n) {
        med1 = arr1[i];
        i++;
    }

    while (j < n) {
        med2 = arr2[j];
        j++;
    }

    return (med1 + med2) / 2;
}

function toggle_string(string){
  return string.split('').map(char => char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase()).join('');
}
